import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {existsSync,readFileSync,unlinkSync} from 'node:fs';
import {calls,server} from './mock-tool-http';
const root='/workspace/native-sdk';const marker=root+'/isolated/tool-owner';const finished=root+'/isolated/tool-finished';for(const p of [marker,finished])if(existsSync(p))unlinkSync(p);
const until=async(p:any)=>{for(let i=0;i<500;i++){if(p())return;await new Promise(r=>setTimeout(r,20))}throw Error('timeout '+JSON.stringify({calls:calls.length,children:children.map(c=>({pid:c.pid,exitCode:c.exitCode,signalCode:c.signalCode}))}))};
const children:any[]=[];function start(mode:string){const c=spawn(process.execPath,[root+'/opencode-crash-child.ts',mode],{cwd:root,env:process.env,detached:true,stdio:['ignore','pipe','pipe']});children.push(c);c.stdout.on('data',b=>console.log('CHILD',b.toString().trim()));c.stderr.on('data',b=>console.log('STDERR',b.toString().slice(0,1000)));return c}
try{const first=start('start');await until(()=>existsSync(marker));const shell=Number(readFileSync(marker,'utf8').trim());process.kill(-first.pid,'SIGKILL');await until(()=>first.signalCode!==null);try{process.kill(-shell,'SIGKILL')}catch{try{process.kill(shell,'SIGKILL')}catch{}}
await until(()=>{try{process.kill(shell,0);return false}catch{return true}});
unlinkSync(marker);const before=calls.length;const second=start('recover');let recovered=false;second.stdout.on('data',b=>{if(b.toString().includes('RECOVERY_READY')){assert.equal(calls.length,before);recovered=true}});await until(()=>second.exitCode!==null||second.signalCode!==null);assert.equal(second.exitCode,0);assert.ok(recovered);assert.ok(calls.length>before);assert.ok(calls[before].messages.some((m:any)=>Array.isArray(m.content)&&m.content.some((c:any)=>c.type==='tool_result'&&c.tool_use_id==='tool_crash'&&c.is_error===true)));console.log(JSON.stringify({case:'first-fresh-model-request',oldToolAlreadyError:true}));assert.equal(existsSync(finished),false);assert.equal(existsSync(marker),false);console.log(JSON.stringify({case:'OpenCode-actual-owner-SIGKILL-during-native-shell',ownerDeathObserved:true,externalShellContainmentJoined:true,recoveryZeroModelCalls:true,freshInputWorked:true,completionMarkerAbsentAtStop:true}));}finally{for(const c of children)if(c.exitCode===null&&c.signalCode===null)try{process.kill(-c.pid,'SIGKILL')}catch{}server.close()}
